<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { Head, Link } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

interface Row { enrollment_id:number; nis:string; student_name:string; class_name:string; subject_name:string; materials_read:number; materials_total:number; assignments_submitted:number; assignments_total:number; late_count:number; revision_count:number; average_score:number|null }
const props = defineProps<{ active_term?: { name:string } | null; rows: Row[]; is_student: boolean; personal_attendance?: {present:number;sick:number;permitted:number;absent:number;total:number;percentage:number}|null }>();
const search = ref('');
const selectedClass = ref('');
const classes = computed(() => [...new Set(props.rows.map(r => r.class_name))].sort());
const filtered = computed(() => props.rows.filter(r => (!selectedClass.value || r.class_name === selectedClass.value) && `${r.nis} ${r.student_name} ${r.subject_name}`.toLowerCase().includes(search.value.toLowerCase())));
const totals = computed(() => ({ students: new Set(filtered.value.map(r => r.enrollment_id)).size, material: filtered.value.reduce((n,r) => n+r.materials_read,0), task: filtered.value.reduce((n,r) => n+r.assignments_submitted,0), late: filtered.value.reduce((n,r) => n+r.late_count,0) }));
const ratio = (done:number,total:number) => total ? Math.round(done/total*100) : 0;
</script>

<template><Head title="Progress Belajar"/><AppLayout><main class="view space-y-6 learning-progress-page"><section class="hero-card compact-hero"><div><p class="eyebrow">{{ is_student ? 'Ringkasan belajar saya' : 'Monitoring pembelajaran' }} · {{ active_term?.name ?? 'Belum ada semester aktif' }}</p><h1>{{ is_student ? 'Progress Belajar Saya' : 'Progress Belajar Siswa' }}</h1><p>{{ is_student ? 'Pantau kehadiran, materi yang sudah dipelajari, dan tugas yang telah dikumpulkan.' : 'Pantau materi dibaca, tugas selesai atau terlambat, kebutuhan revisi, dan capaian nilai.' }}</p></div><Link class="secondary-button" href="/pembelajaran">{{ is_student ? 'Buka materi & tugas' : 'Kembali ke pembelajaran' }}</Link></section>
<section v-if="!is_student" class="grade-summary"><div><span>Siswa</span><strong>{{ totals.students }}</strong><small>pada hasil filter</small></div><div><span>Materi dibaca</span><strong>{{ totals.material }}</strong><small>aktivitas tercatat</small></div><div><span>Tugas selesai</span><strong>{{ totals.task }}</strong><small>pengumpulan tercatat</small></div><div><span>Terlambat</span><strong>{{ totals.late }}</strong><small>perlu perhatian</small></div></section>
<section v-if="personal_attendance" class="panel personal-attendance"><div><span>Kehadiran saya</span><strong>{{ personal_attendance.percentage }}%</strong></div><p>Hadir {{ personal_attendance.present }} · Sakit {{ personal_attendance.sick }} · Izin {{ personal_attendance.permitted }} · Alpa {{ personal_attendance.absent }}</p></section>
<section class="panel overflow-hidden"><div v-if="!is_student" class="toolbar progress-toolbar"><input v-model="search" placeholder="Cari siswa atau mata pelajaran"><select v-model="selectedClass"><option value="">Semua kelas</option><option v-for="c in classes" :key="c">{{ c }}</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ is_student ? 'Mata Pelajaran' : 'Siswa' }}</th><th v-if="!is_student">Kelas / Mapel</th><th>Materi</th><th>Tugas</th><th v-if="!is_student">Terlambat</th><th v-if="!is_student">Revisi</th><th>Rerata nilai</th></tr></thead><tbody><tr v-for="row in filtered" :key="`${row.enrollment_id}-${row.subject_name}`"><td><template v-if="is_student"><strong>{{ row.subject_name }}</strong><br><small>{{ row.class_name }}</small></template><template v-else><strong>{{ row.student_name }}</strong><br><small>{{ row.nis }}</small></template></td><td v-if="!is_student">{{ row.class_name }}<br><small>{{ row.subject_name }}</small></td><td><strong>{{ row.materials_read }}/{{ row.materials_total }}</strong><br><small>{{ ratio(row.materials_read,row.materials_total) }}%</small></td><td><strong>{{ row.assignments_submitted }}/{{ row.assignments_total }}</strong><br><small>{{ ratio(row.assignments_submitted,row.assignments_total) }}%</small></td><td v-if="!is_student">{{ row.late_count }}</td><td v-if="!is_student">{{ row.revision_count }}</td><td><strong>{{ row.average_score === null ? '—' : `${row.average_score}%` }}</strong></td></tr><tr v-if="!filtered.length"><td :colspan="is_student ? 4 : 7" class="empty-state">{{ is_student ? 'Aktivitas belajar akan tercatat setelah materi dibaca atau tugas dikumpulkan.' : 'Belum ada data progress untuk filter ini.' }}</td></tr></tbody></table></div></section></main></AppLayout></template>

<style scoped>.compact-hero{display:flex;align-items:center;justify-content:space-between;gap:1rem}.progress-toolbar{display:flex;gap:.75rem;padding:1rem 1.25rem;border-bottom:1px solid var(--line)}.progress-toolbar input{flex:1}.progress-toolbar input,.progress-toolbar select{color:var(--ink);background:var(--surface);border:1px solid var(--line-strong);border-radius:.65rem;padding:.65rem .75rem}.table-wrap{overflow:auto}.data-table small{color:var(--ink-soft)}.empty-state{text-align:center;padding:3rem;color:var(--ink-soft)}.personal-attendance{display:flex;justify-content:space-between;align-items:center;padding:1rem 1.25rem}.personal-attendance span{display:block;color:var(--ink-soft);font-size:.78rem}.personal-attendance strong{font-size:1.5rem;color:var(--primary)}.student-learning-summary{grid-template-columns:repeat(4,minmax(0,1fr))}@media(max-width:760px){.compact-hero{align-items:stretch;flex-direction:column}.progress-toolbar,.personal-attendance{align-items:stretch;flex-direction:column}.student-learning-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
